/** Formats a Date as DD.MM.YYYY. */
export function date(value) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${pad(value.getDate())}.${pad(value.getMonth() + 1)}.${value.getFullYear()}`;
}

